using System.ComponentModel;
using System.Text;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace RestApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// Non-static class — HttpClient and ILogger are constructor-injected by the DI container.
/// </summary>
[McpServerToolType]
public class RestApiTools(HttpClient httpClient, ILogger<RestApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all resources from the REST API. Returns a JSON array.")]
    public async Task<string> ListResources(
        [Description("Maximum number of items to return (1–100)")] int limit = 20,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing resources (limit={Limit})", limit);
        var response = await httpClient.GetStringAsync($"/posts?_limit={limit}", cancellationToken);
        return response;
    }

    [McpServerTool, Description("Get a single resource by its numeric ID.")]
    public async Task<string> GetResource(
        [Description("The resource ID to fetch")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var response = await httpClient.GetAsync($"/posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new resource. Returns the created object as JSON.")]
    public async Task<string> CreateResource(
        [Description("Title for the new resource")] string title,
        [Description("Body content for the new resource")] string body,
        [Description("Author user ID")] int userId = 1,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource for user {UserId}", userId);

        var payload = JsonSerializer.Serialize(new { title, body, userId });
        var content = new StringContent(payload, Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();

        var result = await response.Content.ReadAsStringAsync(cancellationToken);
        return JsonDocument.Parse(result).RootElement.Clone().ToString()
               ?? result;
    }

    [McpServerTool, Description("Search resources by keyword in the title field.")]
    public async Task<string> SearchResources(
        [Description("Search keyword to match against resource titles")] string query,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching resources for '{Query}'", query);
        var encoded = Uri.EscapeDataString(query);
        var response = await httpClient.GetStringAsync($"/posts?title_like={encoded}", cancellationToken);
        return response;
    }
}

